const sites=[['youtube',['youtube.com','youtu.be']],['instagram',['instagram.com']],['facebook',['facebook.com','fb.com']],['telegram',['t.me','telegram.me','telegram.org']],['spotify',['spotify.com']],['tiktok',['tiktok.com']],['discord',['discord.com','discord.gg']],['twitch',['twitch.tv']],['x',['x.com','twitter.com']],['whatsapp',['wa.me','whatsapp.com']],['linkedin',['linkedin.com']],['skoda',['skoda.es','skoda-auto.com','skoda-auto.es','myskoda.com']]];
export function platformFor(url,name=''){let host='';try{host=new URL(url).hostname.toLowerCase();}catch{}for(const [icon,domains]of sites)if(domains.some(d=>host===d||host.endsWith('.'+d)))return icon;if(!host){const n=name.trim().toLowerCase().replace(/\s/g,'');if(n==='myskoda'||n==='škoda'||n==='skoda')return'skoda';if(sites.some(([key])=>key===n))return n;}return null;}
export function platformIcon(url,name=''){const icon=platformFor(url,name);if(!icon)return null;const image=document.createElement('img');image.className='platform-icon';image.src='assets/platforms/'+icon+'.svg';image.alt=icon==='skoda'?'Škoda':icon;image.width=image.height=32;image.loading='lazy';image.onerror=()=>image.remove();return image;}
